@Service @RequiredArgsConstructor
public class AbsenceService {
    private static final Set<String> TYPES=Set.of("MALADIE","INJUSTIFIEE","EVENEMENT_FAMILIAL","MISSION","AUTRE");
    private static final Pattern SAFE_NAME=Pattern.compile("[^A-Za-z0-9._-]");
    private final JdbcTemplate jdbc;
    private final EmployeRepository employes;
    private final UtilisateurRepository utilisateurs;
    private final TypeDocumentRepository typeDocuments;
    private final DocumentEmployeRepository documents;
    private final TempsPlanningService access;
    private final DemandeCongeService demandes;
    private final NotificationService notifications;
    private final ApplicationEventPublisher events;

    @Transactional public Map<String,Object> creer(AbsenceRequest r,String email,String role){
        verifierType(r.type());if(r.dateFin().isBefore(r.dateDebut()))throw new IllegalArgumentException("La date de fin précède la date de début");autoriser(r.employeId(),email,role);verifierPeriodeOuverte(r.dateDebut(),r.dateFin());
        if(chevaucheCongeValide(r.employeId(),r.dateDebut(),r.dateFin()))throw new IllegalArgumentException("Une absence ne peut pas chevaucher un congé déjà validé");
        Boolean overlap=jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM absence WHERE employe_id=? AND date_debut<=? AND date_fin>=?)",Boolean.class,r.employeId(),r.dateFin(),r.dateDebut());if(overlap)throw new IllegalArgumentException("Une absence existe déjà sur cette période ; utilisez sa qualification");
        String type=r.type().trim().toUpperCase();int days=delaiJustificatif();LocalDate deadline=type.equals("MALADIE")?LocalDate.now().plusDays(days):null;
        Long id=jdbc.queryForObject("INSERT INTO absence(employe_id,type,date_debut,date_fin,statut,source,commentaire,date_limite_justificatif) VALUES(?,?,?,?,?,'SAISIE_RH',?,?) RETURNING id",Long.class,r.employeId(),type,r.dateDebut(),r.dateFin(),type.equals("INJUSTIFIEE")?"NON_JUSTIFIEE":"CONSTATEE",r.commentaire(),deadline);access.integrerAbsence(r.employeId(),r.dateDebut(),r.dateFin(),"ABSENCE");jdbc.update("UPDATE anomalie_pointage SET statut='JUSTIFIEE',commentaire_traitement=COALESCE(commentaire_traitement,'') || ' Absence saisie par RH/manager' WHERE employe_id=? AND date BETWEEN ? AND ? AND type='ABSENCE_SANS_CONGE' AND statut='OUVERTE'",r.employeId(),r.dateDebut(),r.dateFin());jdbc.update("UPDATE absence_a_qualifier SET statut='QUALIFIEE' WHERE anomalie_id IN (SELECT id FROM anomalie_pointage WHERE employe_id=? AND date BETWEEN ? AND ? AND type='ABSENCE_SANS_CONGE' AND statut='JUSTIFIEE')",r.employeId(),r.dateDebut(),r.dateFin());audit(userId(email),"CREATION","absence",id,"null","{\"type\":\""+type+"\",\"statut\":\"CONSTATEE\"}");return absence(id);
    }

    @Transactional public Map<String,Object> qualifier(long id,QualificationAbsenceRequest r,String email,String role){
        Map<String,Object>a=absenceLock(id);long emp=num(a,"employe_id");autoriser(emp,email,role);verifierPeriodeOuverte(date(a,"date_debut"),date(a,"date_fin"));if(a.get("anomalie_id")==null||!"A_QUALIFIER".equals(jdbc.queryForObject("SELECT statut FROM absence_a_qualifier WHERE anomalie_id=?",String.class,a.get("anomalie_id"))))throw new IllegalStateException("Seule une absence issue d'une anomalie à qualifier peut être qualifiée");String type=r.type().trim().toUpperCase();if(!type.equals("CONGE"))verifierType(type);
        Long demandeId=null;
        if(type.equals("CONGE")){
            if(!Set.of("RH","ADMIN").contains(role))throw new AccessDeniedException("La conversion en congé avec débit de solde est réservée à la RH");
            if(r.typeCongeId()==null)throw new IllegalArgumentException("typeCongeId est requis pour convertir en congé");
            demandeId=convertirEnConge(a,r.typeCongeId(),email);
            jdbc.update("UPDATE absence SET type='AUTRE',statut='JUSTIFIEE',demande_conge_id=?,commentaire=COALESCE(commentaire,'') || ? WHERE id=?",demandeId," [Qualifiée en congé]",id);
        } else {
            String statut=type.equals("INJUSTIFIEE")?"NON_JUSTIFIEE":type.equals("MALADIE")?"CONSTATEE":"JUSTIFIEE";
            jdbc.update("UPDATE absence SET type=?,statut=? WHERE id=?",type,statut,id);
        }
        jdbc.update("UPDATE absence_a_qualifier SET statut='QUALIFIEE' WHERE anomaly_id=(SELECT anomalie_id FROM absence WHERE id=?)",id);
        jdbc.update("UPDATE anomalie_pointage SET statut='JUSTIFIEE',commentaire_traitement=COALESCE(commentaire_traitement,'') || ? WHERE id=(SELECT anomalie_id FROM absence WHERE id=?)","Absence qualifiée : "+type,id);
        if(demandeId!=null){Map<String,Object>d=jdbc.queryForMap("SELECT type_conge_id,nb_jours,date_debut,date_fin FROM demande_conge WHERE id=?",demandeId);events.publishEvent(new CongeValideEvent(demandeId,emp,num(d,"type_conge_id"),asDate(d.get("date_debut")),asDate(d.get("date_fin")),new java.math.BigDecimal(d.get("nb_jours").toString())));}
        audit(userId(email),"MODIFICATION","absence",id,"{\"statut\":\"CONSTATEE\"}","{\"type\":\""+type+"\",\"statut\":\"QUALIFIEE\"}");return absence(id);
    }

    private Long convertirEnConge(Map<String,Object>a,long typeId,String email){
        LocalDate start=date(a,"date_debut"),end=date(a,"date_fin");
        if(chevaucheCongeValide(num(a,"employe_id"),start,end))throw new IllegalArgumentException("Un congé validé chevauche déjà cette absence");
        Map<String,Object>t=jdbc.queryForMap("SELECT * FROM type_conge WHERE id=? AND actif=true",typeId);if(!Boolean.TRUE.equals(t.get("debite_solde")))throw new IllegalArgumentException("Le type de congé doit débiter un solde");
        Map<Integer,java.math.BigDecimal> byYear=new TreeMap<>();for(int year=start.getYear();year<=end.getYear();year++){LocalDate from=start.isAfter(LocalDate.of(year,1,1))?start:LocalDate.of(year,1,1);LocalDate to=end.isBefore(LocalDate.of(year,12,31))?end:LocalDate.of(year,12,31);java.math.BigDecimal part=demandes.joursAbsence(num(a,"employe_id"),from,to,typeId);if(part.signum()>0)byYear.put(year,part);}
        java.math.BigDecimal days=byYear.values().stream().reduce(java.math.BigDecimal.ZERO,java.math.BigDecimal::add);if(days.signum()<=0)throw new IllegalArgumentException("L'absence ne couvre aucun jour planifié");Map<Integer,Long> balanceIds=new TreeMap<>();
        for(var entry:byYear.entrySet()){int year=entry.getKey();jdbc.update("INSERT INTO solde_conge(employe_id,type_conge_id,annee) VALUES(?,?,?) ON CONFLICT(employe_id,type_conge_id,annee) DO NOTHING",num(a,"employe_id"),typeId,year);Map<String,Object>s=jdbc.queryForMap("SELECT id,acquis,pris,en_attente,reporte,ajuste FROM solde_conge WHERE employe_id=? AND type_conge_id=? AND annee=? FOR UPDATE",num(a,"employe_id"),typeId,year);java.math.BigDecimal available=new java.math.BigDecimal(s.get("acquis").toString()).add(new java.math.BigDecimal(s.get("reporte").toString())).add(new java.math.BigDecimal(s.get("ajuste").toString())).subtract(new java.math.BigDecimal(s.get("pris").toString())).subtract(new java.math.BigDecimal(s.get("en_attente").toString()));if(available.compareTo(entry.getValue())<0&&!Boolean.TRUE.equals(t.get("solde_negatif_autorise")))throw new IllegalStateException("Solde disponible insuffisant pour convertir l'absence en congé");balanceIds.put(year,((Number)s.get("id")).longValue());}
        Integer uid=userId(email);Long demande=jdbc.queryForObject("INSERT INTO demande_conge(employe_id,type_conge_id,date_debut,date_fin,demi_journee_debut,demi_journee_fin,nb_jours,motif,statut,valide_manager_id,date_validation_manager,valide_rh_id,date_validation_rh,date_soumission) VALUES(?,?,?,?,FALSE,FALSE,?,?,'VALIDEE_RH',?,CURRENT_TIMESTAMP,?,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP) RETURNING id",Long.class,num(a,"employe_id"),typeId,start,end,days,"Conversion de l'absence #"+num(a,"id"),uid,uid);
        for(var entry:byYear.entrySet()){long sid=balanceIds.get(entry.getKey());jdbc.update("UPDATE solde_conge SET pris=pris+? WHERE id=?",entry.getValue(),sid);jdbc.update("INSERT INTO mouvement_solde(solde_conge_id,type,quantite,demande_id,date,motif,cree_par_id,cle_idempotence) VALUES(?,'PRISE',?,?,CURRENT_DATE,?,?,?) ON CONFLICT(solde_conge_id,cle_idempotence) WHERE cle_idempotence IS NOT NULL DO NOTHING",sid,entry.getValue(),demande,"Conversion absence #"+num(a,"id"),uid,"ABSENCE:"+num(a,"id")+":PRISE:"+entry.getKey());}return demande;
    }

    @Transactional public long deposerJustificatif(long absenceId,MultipartFile file,String email,String role)throws IOException{
        Map<String,Object>a=absenceLock(absenceId);long emp=num(a,"employe_id");if(!Set.of("RH","ADMIN").contains(role)){if("EMPLOYE".equals(role)){boolean own=jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM employe e JOIN candidat c ON c.id=e.candidat_id WHERE e.id=? AND lower(c.email)=lower(?))",Boolean.class,emp,email);if(!own)throw new AccessDeniedException("Cette absence ne vous appartient pas");}else autoriser(emp,email,role);}verifierPeriodeOuverte(date(a,"date_debut"),date(a,"date_fin"));verifierFichier(file);
        Employe employee=employes.findById(emp).orElseThrow(()->new IllegalArgumentException("Employé introuvable"));Utilisateur user=utilisateurs.findByEmail(email).orElseThrow(()->new IllegalStateException("Utilisateur introuvable"));var typeDoc=typeDocuments.findByCode("JUSTIFICATIF_ABSENCE").orElseThrow(()->new IllegalStateException("Type de document justificatif absent"));
        String ext=extension(file);Path dir=Paths.get("uploads","justificatifs").toAbsolutePath().normalize();Files.createDirectories(dir);String filename=UUID.randomUUID()+"."+ext;Path target=dir.resolve(filename).normalize();if(!target.startsWith(dir))throw new IllegalArgumentException("Nom de fichier invalide");
        try{Files.copy(file.getInputStream(),target);String original=file.getOriginalFilename()==null?filename:SAFE_NAME.matcher(Paths.get(file.getOriginalFilename()).getFileName().toString()).replaceAll("_");if(original.length()>255)original=original.substring(original.length()-255);DocumentEmploye doc=documents.save(DocumentEmploye.builder().employe(employee).type("AUTRE").typeDocument(typeDoc).nomFichier(original).url("/uploads/justificatifs/"+filename).taille(file.getSize()).dateDepot(LocalDateTime.now()).deposePar(user).confidentialite("SENSIBLE").build());Long id=jdbc.queryForObject("INSERT INTO justificatif(absence_id,document_id,statut) VALUES(?,?,'DEPOSE') RETURNING id",Long.class,absenceId,doc.getId());return id;
        }catch(RuntimeException|IOException e){Files.deleteIfExists(target);throw e;}
    }
    private void verifierFichier(MultipartFile file)throws IOException{if(file==null||file.isEmpty()||file.getSize()>maxBytes())throw new IllegalArgumentException("Fichier vide ou trop volumineux");String content=file.getContentType()==null?"":file.getContentType().toLowerCase(Locale.ROOT);byte[] data=file.getBytes();boolean pdf=content.equals("application/pdf")&&starts(data,new byte[]{'%', 'P','D','F','-'});boolean png=content.equals("image/png")&&starts(data,new byte[]{(byte)137,80,78,71,13,10,26,10});boolean jpg=(content.equals("image/jpeg")||content.equals("image/jpg"))&&data.length>=3&&data[0]==(byte)255&&data[1]==(byte)216&&data[2]==(byte)255;if(!(pdf||png||jpg))throw new IllegalArgumentException("Formats autorisés : PDF, PNG ou JPEG");}
    private boolean starts(byte[] b,byte[] prefix){if(b.length<prefix.length)return false;for(int i=0;i<prefix.length;i++)if(b[i]!=prefix[i])return false;return true;}private String extension(MultipartFile f){String t=f.getContentType().toLowerCase(Locale.ROOT);return t.equals("application/pdf")?"pdf":t.equals("image/png")?"png":"jpg";}

    @Transactional public Map<String,Object> traiterJustificatif(long id,boolean accepte,String motif,String email){if(!accepte&&(motif==null||motif.isBlank()))throw new IllegalArgumentException("Le motif du rejet est obligatoire");Map<String,Object>j=jdbc.queryForMap("SELECT j.id,j.absence_id,j.document_id,j.statut,a.employe_id,a.date_debut,a.date_fin FROM justificatif j JOIN absence a ON a.id=j.absence_id WHERE j.id=? FOR UPDATE",id);if(!"DEPOSE".equals(j.get("statut")))throw new IllegalStateException("Ce justificatif a déjà été traité");verifierPeriodeOuverte(asDate(j.get("date_debut")),asDate(j.get("date_fin")));String status=accepte?"VALIDE":"REJETE";Integer uid=userId(email);jdbc.update("UPDATE justificatif SET statut=? WHERE id=?",status,id);jdbc.update("UPDATE document SET statut=?,valide_par_id=?,date_validation=CURRENT_TIMESTAMP,motif_rejet=? WHERE id=?",status,uid,accepte?null:motif,j.get("document_id"));jdbc.update("UPDATE absence SET statut=CASE WHEN ? THEN 'JUSTIFIEE' WHEN date_limite_justificatif<CURRENT_DATE THEN 'NON_JUSTIFIEE' ELSE 'CONSTATEE' END WHERE id=?",accepte,j.get("absence_id"));audit(uid,"MODIFICATION","justificatif",id,"{\"statut\":\"DEPOSE\"}","{\"statut\":\""+status+"\"}");return jdbc.queryForMap("SELECT * FROM justificatif WHERE id=?",id);}

    public List<Map<String,Object>> absences(long employeId,LocalDate du,LocalDate au){return jdbc.queryForList("SELECT a.*,x.statut AS statut_qualification FROM absence a LEFT JOIN absence_a_qualifier x ON x.anomalie_id=a.anomalie_id WHERE a.employe_id=? AND (?::date IS NULL OR a.date_fin>=?) AND (?::date IS NULL OR a.date_debut<=?) ORDER BY a.date_debut DESC,a.id DESC",employeId,du,du,au,au);}
    public List<Map<String,Object>> justificatifs(Long absenceId,String statut){return jdbc.queryForList("SELECT j.id,j.absence_id AS \"absenceId\",j.document_id AS \"documentId\",j.statut,j.date_depot AS \"dateDepot\",d.nom_fichier AS \"nomFichier\",d.url,d.taille,a.employe_id AS \"employeId\" FROM justificatif j JOIN document d ON d.id=j.document_id JOIN absence a ON a.id=j.absence_id WHERE (?::bigint IS NULL OR j.absence_id=?) AND (?::varchar IS NULL OR j.statut=?) ORDER BY j.date_depot DESC",absenceId,absenceId,statut,statut);}
    public long employeIdAbsence(long absenceId){return jdbc.queryForObject("SELECT employe_id FROM absence WHERE id=?",Long.class,absenceId);}
    public List<Map<String,Object>> rechercher(String email,String role,String statut,String type,LocalDate du,LocalDate au,Integer departement){StringBuilder sql=new StringBuilder("SELECT a.*,q.statut AS statut_qualification FROM absence a LEFT JOIN absence_a_qualifier q ON q.anomalie_id=a.anomalie_id WHERE (?::varchar IS NULL OR a.statut=?) AND (?::varchar IS NULL OR a.type=?) AND (?::date IS NULL OR a.date_fin>=?) AND (?::date IS NULL OR a.date_debut<=?) AND (?::integer IS NULL OR EXISTS(SELECT 1 FROM affectation af WHERE af.employe_id=a.employe_id AND af.departement_id=? AND af.date_affectation<=a.date_debut AND (af.date_fin IS NULL OR af.date_fin>=a.date_debut)))");List<Object> args=new ArrayList<>(Arrays.asList(statut,statut,type,type,du,du,au,au,departement,departement));if("EMPLOYE".equals(role)){sql.append(" AND a.employe_id=(SELECT e.id FROM employe e JOIN candidat c ON c.id=e.candidat_id WHERE lower(c.email)=lower(?))");args.add(email);}else if("MANAGER".equals(role)){sql=new StringBuilder("WITH RECURSIVE equipe(id) AS (SELECT e.id FROM employe e JOIN candidat c ON c.id=e.candidat_id WHERE lower(c.email)=lower(?) UNION SELECT af.employe_id FROM affectation af JOIN equipe x ON x.id=af.manager_id WHERE af.date_affectation<=CURRENT_DATE AND (af.date_fin IS NULL OR af.date_fin>=CURRENT_DATE)) "+sql+" AND a.employe_id IN (SELECT id FROM equipe)");args.add(0,email);}sql.append(" ORDER BY a.date_debut DESC,a.id DESC");return jdbc.queryForList(sql.toString(),args.toArray());}
    public long employeConnecte(String email){return jdbc.queryForObject("SELECT e.id FROM employe e JOIN candidat c ON c.id=e.candidat_id WHERE lower(c.email)=lower(?)",Long.class,email);}
    public List<Map<String,Object>> rapport(LocalDate du,LocalDate au,Integer departement){if(au.isBefore(du))throw new IllegalArgumentException("Période invalide");return jdbc.queryForList("WITH temps AS (SELECT af.departement_id,SUM(j.minutes_absence) minutes_absence,SUM(j.minutes_absence+j.minutes_normales) minutes_reference FROM journee_travail j JOIN affectation af ON af.employe_id=j.employe_id AND af.date_affectation<=j.date AND (af.date_fin IS NULL OR af.date_fin>=j.date) WHERE j.date BETWEEN ? AND ? AND (?::integer IS NULL OR af.departement_id=?) GROUP BY af.departement_id),abs AS (SELECT af.departement_id,COUNT(a.id) nb_absences,AVG((a.date_fin-a.date_debut)+1.0) duree_moyenne FROM absence a JOIN affectation af ON af.employe_id=a.employe_id AND af.date_affectation<=a.date_debut AND (af.date_fin IS NULL OR af.date_fin>=a.date_debut) WHERE a.date_debut<=? AND a.date_fin>=? AND (?::integer IS NULL OR af.departement_id=?) GROUP BY af.departement_id) SELECT dep.id departement_id,dep.nom,COALESCE(abs.nb_absences,0) nb_absences,ROUND(COALESCE(abs.duree_moyenne,0)::numeric,2) duree_moyenne_jours,COALESCE(temps.minutes_absence,0) minutes_absence,CASE WHEN COALESCE(temps.minutes_reference,0)=0 THEN 0 ELSE ROUND(100.0*temps.minutes_absence/temps.minutes_reference,2) END taux_absenteisme_pct FROM departement dep LEFT JOIN abs ON abs.departement_id=dep.id LEFT JOIN temps ON temps.departement_id=dep.id WHERE (?::integer IS NULL OR dep.id=?) ORDER BY dep.nom",du,au,departement,departement,au,du,departement,departement,departement,departement);}
    public Map<String,Object> politique(){return jdbc.queryForMap("SELECT * FROM politique_absence WHERE id=1");}
    @Transactional public Map<String,Object> modifierPolitique(int delai,long maxBytes){if(delai<0||maxBytes<1||maxBytes>52_428_800L)throw new IllegalArgumentException("Paramètres de justificatif invalides");jdbc.update("UPDATE politique_absence SET delai_justificatif_jours=?,taille_max_justificatif_octets=? WHERE id=1",delai,maxBytes);return politique();}

    @org.springframework.scheduling.annotation.Scheduled(cron="0 20 3 * * *",zone="Indian/Antananarivo") @Transactional public void traiterEcheances(){jdbc.update("UPDATE absence SET statut='NON_JUSTIFIEE' WHERE date_limite_justificatif<CURRENT_DATE AND statut='CONSTATEE' AND NOT EXISTS(SELECT 1 FROM justificatif j WHERE j.absence_id=absence.id AND j.statut='VALIDE') AND NOT EXISTS(SELECT 1 FROM periode_temps p WHERE p.statut<>'OUVERTE' AND make_date(p.annee::int,p.mois::int,1)<=absence.date_fin AND (make_date(p.annee::int,p.mois::int,1)+INTERVAL '1 month - 1 day')::date>=absence.date_debut)");}
    @org.springframework.scheduling.annotation.Scheduled(cron="0 30 8 * * *",zone="Indian/Antananarivo") @Transactional public void rappelerJustificatifs(){var rows=jdbc.queryForList("SELECT a.id,a.employe_id FROM absence a WHERE a.statut='CONSTATEE' AND a.date_limite_justificatif>=CURRENT_DATE AND a.date_limite_justificatif<=CURRENT_DATE+1 AND NOT EXISTS(SELECT 1 FROM justificatif j WHERE j.absence_id=a.id AND j.statut='VALIDE') AND NOT EXISTS(SELECT 1 FROM absence_rappel_justificatif r WHERE r.absence_id=a.id AND r.date_rappel=CURRENT_DATE)");for(var row:rows){long id=num(row,"id"),emp=num(row,"employe_id");String email=jdbc.queryForObject("SELECT c.email FROM employe e JOIN candidat c ON c.id=e.candidat_id WHERE e.id=?",String.class,emp);utilisateurs.findByEmail(email).ifPresent(u->notifications.notifyUser(u,"Merci de déposer le justificatif demandé pour votre absence #"+id,null));jdbc.update("INSERT INTO absence_rappel_justificatif(absence_id,date_rappel) VALUES(?,CURRENT_DATE) ON CONFLICT DO NOTHING",id);}}

    private void autoriser(long emp,String email,String role){if(Set.of("RH","ADMIN").contains(role))return;boolean manager=role.equals("MANAGER");access.verifierAccesEmploye(emp,email,manager);if(!manager)throw new AccessDeniedException("Cette action est réservée à la RH ou au manager");}
    private void verifierPeriodeOuverte(LocalDate du,LocalDate au){List<Map<String,Object>> periods=jdbc.queryForList("SELECT statut FROM periode_temps p WHERE make_date(p.annee::int,p.mois::int,1)<=? AND (make_date(p.annee::int,p.mois::int,1)+INTERVAL '1 month - 1 day')::date>=? FOR UPDATE",au,du);if(periods.stream().anyMatch(p->!"OUVERTE".equals(p.get("statut"))))throw new IllegalStateException("La période de temps est verrouillée ; sa réouverture est requise");}
    private void audit(Integer uid,String action,String entity,long id,String before,String after){jdbc.update("INSERT INTO journal_audit(utilisateur_id,role,action,entite,entite_id,ancienne_valeur,nouvelle_valeur) VALUES(?,(SELECT r.code FROM utilisateur u JOIN role r ON r.id=u.role_id WHERE u.id=?),?,?,?,CAST(? AS jsonb),CAST(? AS jsonb))",uid,uid,action,entity,id,before,after);}
    private boolean chevaucheCongeValide(long emp,LocalDate du,LocalDate au){return jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM demande_conge WHERE employe_id=? AND statut='VALIDEE_RH' AND date_debut<=? AND date_fin>=?)",Boolean.class,emp,au,du);}
    private int delaiJustificatif(){return jdbc.queryForObject("SELECT delai_justificatif_jours FROM politique_absence WHERE id=1",Integer.class);}private long maxBytes(){return jdbc.queryForObject("SELECT taille_max_justificatif_octets FROM politique_absence WHERE id=1",Long.class);}
    private Map<String,Object> absence(long id){return jdbc.queryForMap("SELECT * FROM absence WHERE id=?",id);}private Map<String,Object> absenceLock(long id){return jdbc.queryForMap("SELECT * FROM absence WHERE id=? FOR UPDATE",id);}private void verifierType(String type){if(type==null||!TYPES.contains(type.trim().toUpperCase()))throw new IllegalArgumentException("Type d'absence invalide");}
    private long num(Map<String,Object>m,String k){return ((Number)m.get(k)).longValue();}private LocalDate date(Map<String,Object>m,String k){return asDate(m.get(k));}private LocalDate asDate(Object o){return o instanceof LocalDate d?d:((java.sql.Date)o).toLocalDate();}private int userId(String email){return utilisateurs.findByEmail(email).orElseThrow().getId();}
}
